std::vector<std::string> names;

// 1. Capacity management: reserve()
// Prevents costly reallocations during inserts
names.reserve(1000);

// 2. Efficient insertion for complex types
names.emplace_back("Alice"); // Construct in place

// 3. Swap and pop (Efficient element removal without preserve order)
std::size_t idx = 5;
std::swap(names[idx], names.back());
names.pop_back();

// 4. Free excess memory
names.shrink_to_fit();
